===================================================================
--- index.html
+++ index.html
@@ -20,6 +20,62 @@
 <div class="panel glass" id="panel"><div class="panel-head"><div><h2 id="panelTitle">Spawn menu</h2><p id="panelSub">Bring a little more chaos to the playground.</p></div><button class="close" id="closePanel">×</button></div><div class="panel-body" id="panelBody"></div></div>
 <div class="screen" id="startScreen"><div class="intro"><div class="intro-top"><span>✦</span> A 3D sandbox adventure <span>✦</span></div><h1>Make a little<br><em>beautiful chaos.</em></h1><p>Take Konata or Niko out for a stroll, meet the locals, build a silly scene, and boop things with your bubble blaster. Your playground, your rules.</p><div class="intro-bottom"><button class="start" id="startBtn">ENTER THE PLAYGROUND&nbsp; →</button><div class="controls-copy"><b>W A S D</b> move &nbsp;·&nbsp; <b>SPACE</b> hop &nbsp;·&nbsp; <b>CLICK</b> pop bubbles<br><b>Q</b> spawn menu &nbsp;·&nbsp; <b>TAB</b> character &nbsp;·&nbsp; <b>E</b> grab / drop</div></div><div class="tagline" style="margin-top:26px">Made for wandering · tap-friendly · no wrong answers</div></div></div>
 <script type="module">
 import * as THREE from 'three';
-</script>
+
+const $=s=>document.querySelector(s), scene=new THREE.Scene();
+scene.background=new THREE.Color('#a9d8e6'); scene.fog=new THREE.Fog('#a9d8e6',34,105);
+const camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,.1,180);
+const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; $('#game').appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight('#eafaff','#62765d',2.1)); const sun=new THREE.DirectionalLight('#fff1d2',3.3); sun.position.set(-16,28,12); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;scene.add(sun);
+const mats={ground:new THREE.MeshStandardMaterial({color:'#86aa72',roughness:1}), path:new THREE.MeshStandardMaterial({color:'#d7c59f',roughness:1}), white:new THREE.MeshStandardMaterial({color:'#fff7ed',roughness:.72}), skin:new THREE.MeshStandardMaterial({color:'#ffe0c9',roughness:.82}), blue:new THREE.MeshStandardMaterial({color:'#2e82c5',roughness:.7}), hair:new THREE.MeshStandardMaterial({color:'#287bc1',roughness:.78}), darkHair:new THREE.MeshStandardMaterial({color:'#342a35',roughness:.78}), red:new THREE.MeshStandardMaterial({color:'#dc6271'}), gold:new THREE.MeshStandardMaterial({color:'#f1c86c',metalness:.18,roughness:.45}), pants:new THREE.MeshStandardMaterial({color:'#334967',roughness:.9}), boot:new THREE.MeshStandardMaterial({color:'#413d50',roughness:.8}), eye:new THREE.MeshStandardMaterial({color:'#65bce0',roughness:.25}), black:new THREE.MeshStandardMaterial({color:'#25313f'}), wood:new THREE.MeshStandardMaterial({color:'#a96d4b',roughness:.9}), mint:new THREE.MeshStandardMaterial({color:'#86d5bb',roughness:.7}), pink:new THREE.MeshStandardMaterial({color:'#f29aaa',roughness:.75}), stone:new THREE.MeshStandardMaterial({color:'#9babb0',roughness:1}), glass:new THREE.MeshStandardMaterial({color:'#b8e4ed',roughness:.2,metalness:.1})};
+const mat=c=>new THREE.MeshStandardMaterial({color:c,roughness:.78});
+const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,16,12), cylGeo=new THREE.CylinderGeometry(1,1,1,12), coneGeo=new THREE.ConeGeometry(1,1,12);
+function mesh(geo,material,parent,pos=[0,0,0],scale=[1,1,1]){const m=new THREE.Mesh(geo,material);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+const world=new THREE.Group();scene.add(world); let ground,activeMap='Sunnyvale',worldDecor=[];
+function makeGround(){if(ground)world.remove(ground);ground=mesh(boxGeo,mats.ground,world,[0,-.55,0],[180,1,180]); ground.receiveShadow=true;}
+makeGround();
+function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);mesh(cylGeo,mat('#80604b'),g,[0,1.05*s,0],[.22*s,2.1*s,.22*s]);for(let i=0;i<3;i++){const c=mesh(sphereGeo,mat(i===1?'#63966c':'#79aa78'),g,[0,(2.3+i*.42)*s,0],[.92*s,.75*s,.92*s]);}worldDecor.push(g)}
+function buildMap(type='Sunnyvale'){
+ activeMap=type; world.children.slice().forEach(o=>{if(o!==ground)world.remove(o)}); worldDecor=[]; makeGround();
+ const road=mesh(boxGeo,mats.path,world,[0,-.03,-4],[52,.12,7]);
+ for(let i=-5;i<=5;i++){mesh(boxGeo,mat('#f3e7c7'),world,[i*4,-.01,-4],[1.6,.03,.13])}
+ // cozy garden borders and plaza
+ mesh(boxGeo,mat('#d4c396'),world,[0,-.03,5],[29,.13,20]);
+ for(const [x,z,s] of [[-17,-14,1.1],[18,-13,1.2],[-20,10,.9],[20,12,1.1],[-13,19,.8],[14,20,.8],[-29,-3,1],[29,2,1.2]]) tree(x,z,s);
+ for(let i=0;i<7;i++){const x=-20+i*6.5; const h=3+Math.random()*5; const b=mesh(boxGeo,mat(['#efb49c','#c9b8de','#e8d895','#9fcaca'][i%4]),world,[x,h/2,-19],[4.3,h,5]);mesh(boxGeo,mats.white,world,[x,h*.72,-16.43],[3.6,.2,.1]); for(let j=0;j<3;j++)mesh(boxGeo,mats.glass,world,[x-1.1+j*1.1,h*.46,-16.42],[.55,.65,.1]);}
+ // benches, flower beds, lamps
+ for(const [x,z] of [[-7,1],[8,2],[-14,-8],[13,10]]){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);mesh(boxGeo,mats.wood,g,[0,.55,0],[2.5,.18,.7]);for(const a of [-.85,.85])mesh(boxGeo,mats.wood,g,[a,.28,0],[.16,.52,.62]);for(let k=-1;k<=1;k++)mesh(boxGeo,mats.wood,g,[k*.85,.23,-.2],[.12,.48,.12]);}
+ for(let i=0;i<9;i++){const a=i/9*Math.PI*2; const x=Math.cos(a)*13,z=Math.sin(a)*11+3;const f=mesh(sphereGeo,mat(['#f8b4a0','#fff0ad','#b4cffa','#d3a9dc'][i%4]),world,[x,.28,z],[.2,.36,.2]);}
+ if(type!=='Sunnyvale'){
+   if(type==='Grassland'){world.children.filter(o=>o!==ground).forEach(o=>{if(o.geometry===boxGeo && o!==road)o.visible=false});for(let i=0;i<24;i++)tree((Math.random()-.5)*68,(Math.random()-.5)*65,.5+Math.random()*.55);}
+   if(type==='Testing Arena'){mesh(boxGeo,mat('#aeb9bd'),world,[0,-.08,0],[42,.2,42]); for(let x=-16;x<=16;x+=8)for(let z=-16;z<=16;z+=8){if(Math.random()<.58)prop('crate',[x,.7,z],false)} }
+   if(type==='Empty Sandbox'){world.children.filter(o=>o!==ground).forEach(o=>o.visible=false);}
+   if(type==='Factory'||type==='School'||type==='Mall'||type==='Restaurant'||type==='City'){for(let i=0;i<3;i++){let b=mesh(boxGeo,mat(type==='Factory'?'#879398':type==='Restaurant'?'#d88167':'#d6dbe0'),world,[-10+i*10,3,-23],[8,6,7]);mesh(boxGeo,mats.glass,world,[-10+i*10,3,-19.45],[6,2.5,.1]);if(type==='Factory')mesh(cylGeo,mats.stone,world,[-13+i*10,8,-23],[1,8,1]);}}
+ }
+ $('#worldStatus').textContent=type+' • Free roam';
+}
+function character(kind='Konata',x=0,z=3){
+ const root=new THREE.Group();root.position.set(x,0,z);world.add(root);const torso=new THREE.Group();root.add(torso);
+ const niko=kind==='Niko', skin=niko?mat('#e9c398'):mats.skin, hair=niko?mats.darkHair:mats.hair, shirt=niko?mats.red:mats.white;
+ mesh(sphereGeo,skin,torso,[0,1.58,0],[.39,.42,.3]);
+ // ears/side locks
+ if(niko){for(const side of [-1,1]){const ear=mesh(coneGeo,mats.darkHair,torso,[side*.42,2.02,.02],[.2,.7,.2]);ear.rotation.z=-side*.25;mesh(coneGeo,mat('#eac58c'),torso,[side*.42,2.06,.08],[.1,.42,.1]).rotation.z=-side*.25;}}
+ else {for(const side of [-1,1]){mesh(sphereGeo,hair,torso,[side*.34,1.62,-.04],[.18,.48,.2]);}}
+ // hair cap and bangs
+ mesh(sphereGeo,hair,torso,[0,1.88,-.02],[.43,.34,.36]);
+ for(let i=-2;i<=2;i++){let bang=mesh(coneGeo,hair,torso,[i*.13,1.75,.26],[.12,.31,.12]);bang.rotation.x=.18;}
+ if(!niko){const ah=mesh(coneGeo,hair,torso,[.06,2.22,-.02],[.09,.34,.09]);ah.rotation.z=-.42;for(let s of [-1,1])mesh(boxGeo,hair,torso,[s*.25,1.35,-.12],[.22,.44,.2]);}
+ else {mesh(cylGeo,mats.gold,torso,[0,2.13,-.04],[.49,.1,.4]);mesh(cylGeo,mat('#d8b15d'),torso,[0,2.28,-.04],[.29,.24,.28]);mesh(sphereGeo,mat('#f6d982'),torso,[0,2.43,-.04],[.09,.1,.09]);}
+ // face
+ for(let s of [-1,1]){const eye=mesh(sphereGeo,niko?mats.black:mats.eye,torso,[s*.145,1.61,.274],[.055,.075,.035]);mesh(sphereGeo,mats.white,torso,[s*.13,1.65,.3],[.022,.025,.018]);}
+ const mouth=mesh(boxGeo,mat(niko?'#764c46':'#d27a83'),torso,[0,1.47,.294],[.08,.018,.018]);
+ const body=mesh(boxGeo,shirt,torso,[0,1.03,0],[.56,.66,.36]);
+ if(!niko){mesh(boxGeo,mats.blue,torso,[0,.86,.19],[.16,.34,.035]);mesh(boxGeo,mat('#8d293a'),torso,[0,.71,.22],[.48,.08,.04]);}
+ else {mesh(boxGeo,mats.gold,torso,[0,1.03,.19],[.18,.36,.035]);mesh(boxGeo,mats.white,torso,[0,.72,.01],[.56,.2,.37]);}
+ // simple articulated legs and feet
+ const limbs=[];for(let s of [-1,1]){const leg=new THREE.Group();leg.position.set(s*.16,.67,0);torso.add(leg);mesh(boxGeo,niko?mats.white:mats.pants,leg,[0,-.22,0],[.2,.48,.24]);mesh(boxGeo,mats.boot,leg,[0,-.45,.09],[.24,.15,.37]);limbs.push(leg);const arm=new THREE.Group();arm.position.set(s*.34,1.25,0);torso.add(arm);mesh(boxGeo,shirt,arm,[0,-.21,0],[.17,.48,.19]);mesh(sphereGeo,skin,arm,[0,-.46,.01],[.1,.1,.1]);limbs.push(arm);}
+ root.userData={kind,torso,limbs,body,mouth,health:100,velY:0,onGround:true,ai:false,walk:Math.random()*7,action:'idle',target:null};return root;
+}
+let player=character('Konata',0,3), partner=character('Niko',-3,1);partner.userData.ai=true;
+
 </body></html>
\ No newline at end of file

