let player=character('Konata',0,3), partner=character('Niko',-3,1);partner.userData.ai=true;
const props=[],npcs=[partner],bubbles=[];let held=null,ammo=Infinity,health=100,isPaused=false,started=false,walkTime=0,shootCooldown=0;
function prop(type,pos=[0,0,0],register=true){const g=new THREE.Group();g.position.set(...pos);world.add(g);let obj;
 if(type==='Barrel'||type==='Explosive barrel'){obj=mesh(cylGeo,mat(type==='Explosive barrel'?'#d97563':'#b87944'),g,[0,.55,0],[.62,1.1,.62]);mesh(cylGeo,mats.black,g,[0,.25,0],[.64,.07,.64]);mesh(cylGeo,mats.black,g,[0,.83,0],[.64,.07,.64]);g.userData={type,health:type==='Explosive barrel'?1:3,explode:type==='Explosive barrel'};}
 else if(type==='Crate'||type==='Furniture'||type==='Sofa'){obj=mesh(boxGeo,type==='Sofa'?mat('#6a8293'):mats.wood,g,[0,type==='Sofa'?.5:.5,0],type==='Sofa'?[1.6,.6,.75]:[1,1,1]);if(type==='Crate'){mesh(boxGeo,mat('#c99661'),g,[0,.5,.505],[.8,.8,.025]);}g.userData={type,health:3};}
 else if(type==='Vehicle'){obj=mesh(boxGeo,mat('#e39c63'),g,[0,.62,0],[2.5,.85,1.3]);mesh(boxGeo,mats.glass,g,[0,1.15,-.05],[1.2,.36,1.15]);for(let x of [-.8,.8])for(let z of [-.72,.72])mesh(cylGeo,mats.black,g,[x,.28,z],[.32,.16,.32]);g.userData={type,health:8};}
 else if(type==='Building'){obj=mesh(boxGeo,mat('#d7d1bf'),g,[0,1.5,0],[4,3,3]);mesh(boxGeo,mats.glass,g,[0,2,1.52],[2,.8,.06]);g.userData={type,health:8};}
 else if(type==='Lamp'){obj=mesh(cylGeo,mats.black,g,[0,1.7,0],[.12,3.4,.12]);mesh(sphereGeo,mats.gold,g,[0,3.45,0],[.23,.23,.23]);g.userData={type,health:2};}
 else if(type==='NPC'||type==='Human NPC'||type==='Custom NPC'){let c=character(type==='Custom NPC'?'Guest':'Human',0,0);world.remove(c);g.add(c);c.position.set(0,0,0);c.userData.ai=true;c.userData.walk=Math.random()*10;obj=c;g.userData={type,health:100,isNpc:true};npcs.push(c);}
 else if(type==='Konata'||type==='Niko'){let c=character(type);world.remove(c);g.add(c);c.position.set(0,0,0);npcs.push(c);c.userData.ai=true;obj=c;g.userData={type,health:100,isNpc:true};}
 else {obj=mesh(sphereGeo,mat('#91cfe3'),g,[0,.4,0],[.5,.5,.5]);g.userData={type,health:2};}
 props.push(g);return g;}
function popup(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(popup.timer);popup.timer=setTimeout(()=>t.classList.remove('show'),1900)}
function panelOpen(title,sub,html){$('#panelTitle').textContent=title;$('#panelSub').textContent=sub;$('#panelBody').innerHTML=html;$('#panel').classList.add('open');}
function closePanel(){$('#panel').classList.remove('open')}
const spawnItems=[['Characters',[['Konata','Playable pal'],['Niko','Onion-headed hero'],['Human NPC','Wandering local'],['Custom NPC','Fresh new friend']]],['Props',[['Furniture','Breakable chair-sized block'],['Sofa','Comfy and breakable'],['Barrel','Bouncy barrel'],['Explosive barrel','Extra pop!'],['Vehicle','Tiny drivable-looking car'],['Building','A blocky little building'],['Lamp','Street decoration'],['Crate','Stackable crate']]]];
function openSpawn(){let html='';for(const [group,items] of spawnItems){html+=`<div class="section">${group}</div><div class="grid">`;for(const [name,desc] of items)html+=`<button class="tile spawn-item" data-type="${name}"><b>${name}</b><span>${desc}</span></button>`;html+='</div>'}html+='<div class="section">Worlds</div>'+['Sunnyvale','City','Restaurant','School','Mall','Grassland','Factory','Testing Arena','Empty Sandbox'].map(m=>`<button class="map-choice" data-map="${m}"><b>${m}</b><span>Load this playground</span></button>`).join('');panelOpen('Spawn menu','Pick an item, pal. It appears right in front of you.',html);$('#panelBody').querySelectorAll('.spawn-item').forEach(b=>b.onclick=()=>{const p=player.position.clone().add(new THREE.Vector3(Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y)).multiplyScalar(3));const o=prop(b.dataset.type,[p.x,0,p.z]);popup(`${b.dataset.type} spawned!`)});$('#panelBody').querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{buildMap(b.dataset.map);popup(`${b.dataset.map} loaded`);openSpawn()});}
function openMaps(){panelOpen('Choose a playground','Every world is a fresh little sandbox.',['Sunnyvale','City','Restaurant','School','Mall','Grassland','Factory','Testing Arena','Empty Sandbox'].map(m=>`<button class="map-choice ${m===activeMap?'active':''}" data-map="${m}"><b>${m}</b><span>${m===activeMap?'You are here now':'Take a little trip'}</span></button>`).join(''));$('#panelBody').querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{buildMap(b.dataset.map);openMaps();popup(`${b.dataset.map} loaded`)});}
function openStyle(){panelOpen('Style corner','A few quick outfit swaps and color experiments.',`<div class="section">Play as</div><div class="grid"><button class="tile ${player.userData.kind==='Konata'?'active':''}" data-char="Konata"><b>Konata</b><span>Blue-haired gamer</span></button><button class="tile ${player.userData.kind==='Niko'?'active':''}" data-char="Niko"><b>Niko</b><span>Little hat, big heart</span></button></div><div class="section">Outfit colors</div><label class="row">Top color <input type="color" id="topColor" value="${player.userData.body.material.color.getHexString()}"></label><label class="row">Hair color <input type="color" id="hairColor" value="${(player.userData.kind==='Niko'?'#342a35':'#287bc1')}"></label><label class="row">Accessory<select class="select" id="accessory"><option>None</option><option>Star clip</option><option>Flower pin</option></select></label><div class="section" style="margin-top:17px">Coming along</div><div style="font-size:11px;color:#aab8ca;line-height:1.6">This playground is a lightweight prototype: outfit colors update on the character; each character has a fitted, attached outfit silhouette.</div>`);$('#panelBody').querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>switchCharacter(b.dataset.char));$('#topColor').oninput=e=>{player.userData.body.material=mat(e.target.value)};$('#hairColor').oninput=e=>{player.userData.torso.traverse(o=>{if(o.isMesh&&o.material.color&&o.material!==player.userData.body.material){if(o.position.y>1.7)o.material=mat(e.target.value)}})};}
function switchCharacter(name){if(player.userData.kind===name){popup(`You're already ${name}!`);return}const old=player, pos=old.position.clone();world.remove(old);player=character(name,pos.x,pos.z);$('#characterName').textContent=name==='Konata'?'Konata Izumi':'Niko';closePanel();popup(`Now playing ${name}!`)}
$('#spawnBtn').onclick=openSpawn;$('#mobileMenu').onclick=openSpawn;$('#mapBtn').onclick=openMaps;$('#customBtn').onclick=openStyle;$('#closePanel').onclick=closePanel;$('#startBtn').onclick=()=>{$('#startScreen').style.display='none';started=true;popup('Welcome to Sunnyvale!')};$('#pauseBtn').onclick=()=>{isPaused=!isPaused;$('#pauseOverlay').classList.toggle('show',isPaused)};

