function prop(type,pos=[0,0,0]){const g=new THREE.Group();g.position.set(...pos);world.add(g);let obj;if(type==='Barrel'||type==='Explosive barrel'){obj=mesh(cylGeo,mat(type==='Explosive barrel'?'#d97563':'#b87944'),g,[0,.55,0],[.62,1.1,.62]);mesh(cylGeo,mats.black,g,[0,.25,0],[.64,.07,.64]);mesh(cylGeo,mats.black,g,[0,.83,0],[.64,.07,.64]);g.userData={type,health:type==='Explosive barrel'?1:3,explode:type==='Explosive barrel'};}else if(type==='Crate'||type==='Furniture'||type==='Sofa'){obj=mesh(boxGeo,type==='Sofa'?mat('#6a8293'):mats.wood,g,[0,.5,0],type==='Sofa'?[1.6,.6,.75]:[1,1,1]);if(type==='Crate')mesh(boxGeo,mat('#c99661'),g,[0,.5,.505],[.8,.8,.025]);g.userData={type,health:3};}else if(type==='Vehicle'){obj=mesh(boxGeo,mat('#e39c63'),g,[0,.62,0],[2.5,.85,1.3]);mesh(boxGeo,mats.glass,g,[0,1.15,-.05],[1.2,.36,1.15]);for(let x of [-.8,.8])for(let z of [-.72,.72])mesh(cylGeo,mats.black,g,[x,.28,z],[.32,.16,.32]);g.userData={type,health:8};}else if(type==='Building'){obj=mesh(boxGeo,mat('#d7d1bf'),g,[0,1.5,0],[4,3,3]);mesh(boxGeo,mats.glass,g,[0,2,1.52],[2,.8,.06]);g.userData={type,health:8};}else if(type==='Lamp'){obj=mesh(cylGeo,mats.black,g,[0,1.7,0],[.12,3.4,.12]);mesh(sphereGeo,mats.gold,g,[0,3.45,0],[.23,.23,.23]);g.userData={type,health:2};}else if(['NPC','Human NPC','Custom NPC','Konata','Niko'].includes(type)){let c=character(type==='Custom NPC'?'Guest':type==='Human NPC'?'Human':type);world.remove(c);g.add(c);c.position.set(0,0,0);c.userData.ai=true;c.userData.walk=Math.random()*10;obj=c;npcs.push(c);g.userData={type,health:100,isNpc:true};}else{obj=mesh(sphereGeo,mat('#91cfe3'),g,[0,.4,0],[.5,.5,.5]);g.userData={type,health:2};}props.push(g);return g;}
