function openStyle(){panelOpen('Style corner','Quick outfit swaps and color experiments.',`<div class="section">Play as</div><div class="grid"><button class="tile" data-char="Konata"><b>Konata</b><span>Blue-haired gamer</span></button><button class="tile" data-char="Niko"><b>Niko</b><span>Little hat, big heart</span></button></div><div class="section">Outfit colors</div><label class="row">Top color <input type="color" id="topColor" value="${player.userData.body.material.color.getHexString()}"></label><label class="row">Hair color <input type="color" id="hairColor" value="${player.userData.kind==='Niko'?'#342a35':'#287bc1'}"></label><label class="row">Accessory<select class="select"><option>None</option><option>Star clip</option><option>Flower pin</option></select></label><div style="font-size:11px;color:#aab8ca;line-height:1.6;margin-top:12px">Your outfit updates live. More outfit pieces can be added here.</div>`);$('#panelBody').querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>switchCharacter(b.dataset.char));$('#topColor').oninput=e=>player.userData.body.material=mat(e.target.value);$('#hairColor').oninput=e=>player.userData.torso.traverse(o=>{if(o.isMesh&&o.position.y>1.7)o.material=mat(e.target.value)})}
function switchCharacter(name){if(player.userData.kind===name){popup(`You're already ${name}!`);return}const old=player,pos=old.position.clone();world.remove(old);player=character(name,pos.x,pos.z);$('#characterName').textContent=name==='Konata'?'Konata Izumi':'Niko';closePanel();popup(`Now playing ${name}!`)}
$('#spawnBtn').onclick=openSpawn;$('#mobileMenu').onclick=openSpawn;$('#mapBtn').onclick=openMaps;$('#customBtn').onclick=openStyle;$('#closePanel').onclick=closePanel;$('#startBtn').onclick=()=>{$('#startScreen').style.display='none';started=true;popup('Welcome to Sunnyvale!')};$('#pauseBtn').onclick=()=>{isPaused=!isPaused;$('#pauseOverlay').classList.toggle('show',isPaused)};

</body></html>

