$('#pauseBtn').onclick=()=>{isPaused=!isPaused;$('#pauseOverlay').classList.toggle('show',isPaused)};
const keys={};let yaw=0,pitch=.18,mouseDown=false,moveTouch={x:0,y:0};const raycaster=new THREE.Raycaster();
function shoot(){if(!started||isPaused||shootCooldown>0)return;shootCooldown=.25;const dir=new THREE.Vector3();camera.getWorldDirection(dir);const origin=player.position.clone().add(new THREE.Vector3(0,1.35,0));const b=mesh(sphereGeo,mat('#a7f2ef'),scene,origin.toArray(),[.11,.11,.11]);bubbles.push({mesh:b,vel:dir.multiplyScalar(24),life:2});popup('Pop!');const ray=new THREE.Raycaster(origin,dir,0,20);const hits=ray.intersectObjects(world.children,true);if(hits.length){let target=hits.find(h=>h.object!==player&&h.object!==partner);if(target){let p=target.object;while(p.parent&&p.parent!==world)p=p.parent;if(p.userData.health){p.userData.health--;if(p.userData.health<=0){if(p.userData.explode){for(const o of props){if(o.position.distanceTo(p.position)<6)o.userData.health=0}popup('Boom! Everyone okay?')}world.remove(p);const ix=props.indexOf(p);if(ix>=0)props.splice(ix,1)}else{p.scale.multiplyScalar(.94)}}}}}
function pick(){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const hit=ray.intersectObjects(props,true)[0];if(hit){let p=hit.object;while(p.parent&&p.parent!==world)p=p.parent;if(held===p){held=null;popup('Dropped it.');}else if(p.position.distanceTo(player.position)<6){held=p;popup('Grabbed! Press E to drop.')}}}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyQ'){openSpawn()}if(e.code==='Tab'){e.preventDefault();switchCharacter(player.userData.kind==='Konata'?'Niko':'Konata')}if(e.code==='KeyE')pick();if(e.code==='Escape'){isPaused=!isPaused;$('#pauseOverlay').classList.toggle('show',isPaused);closePanel()}});window.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',e=>{if(!started||$('#panel').classList.contains('open'))return;shoot()});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('mousemove',e=>{if(mouseDown){yaw-=e.movementX*.003;pitch=Math.max(-.1,Math.min(.65,pitch+e.movementY*.002))}});renderer.domElement.addEventListener('mousedown',e=>{if(e.button===2)mouseDown=true});window.addEventListener('mouseup',()=>mouseDown=false);
function stick(el,cb){const nub=el.querySelector('.nub');let active=false;function update(e){const r=el.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,len=Math.hypot(dx,dy),k=len>max?max/len:1,x=dx*k,y=dy*k;nub.style.left=`calc(50% + ${x}px)`;nub.style.top=`calc(50% + ${y}px)`;cb(x/max,y/max)}el.addEventListener('pointerdown',e=>{active=true;el.setPointerCapture(e.pointerId);update(e)});el.addEventListener('pointermove',e=>{if(active)update(e)});el.addEventListener('pointerup',()=>{active=false;nub.style.left='50%';nub.style.top='50%';cb(0,0)});el.addEventListener('pointercancel',()=>{active=false;cb(0,0)})}stick($('#moveStick'),(x,y)=>moveTouch={x,y});stick($('#lookStick'),(x,y)=>{yaw-=x*.025;pitch=Math.max(-.1,Math.min(.65,pitch+y*.015))});$('#fireBtn').onpointerdown=e=>{e.preventDefault();shoot()};
function tick(dt){if(!isPaused){shootCooldown=Math.max(0,shootCooldown-dt);const speed=(keys.ShiftLeft||keys.ShiftRight)?8:4.7;let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-moveTouch.y;let r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveTouch.x;let v=new THREE.Vector3(r,0,-f);if(v.length()>1)v.normalize();v.applyAxisAngle(new THREE.Vector3(0,1,0),yaw);player.position.addScaledVector(v,speed*dt);player.position.x=THREE.MathUtils.clamp(player.position.x,-78,78);player.position.z=THREE.MathUtils.clamp(player.position.z,-78,78);if(v.length()>.02){player.rotation.y=Math.atan2(-v.x,-v.z);walkTime+=dt*speed;player.userData.limbs.forEach((limb,i)=>limb.rotation.x=Math.sin(walkTime+(i%2)*Math.PI)*.65)}else player.userData.limbs.forEach(l=>l.rotation.x*=.8);if(keys.Space&&player.userData.onGround){player.userData.velY=7;player.userData.onGround=false}player.userData.velY-=18*dt;player.position.y+=player.userData.velY*dt;if(player.position.y<0){player.position.y=0;player.userData.velY=0;player.userData.onGround=true}
 for(const c of npcs){if(c===player||!c.parent)continue;c.userData.walk+=dt;const d=c.position.distanceTo(player.position);if(c.userData.fleeUntil>Date.now()){const away=c.position.clone().sub(player.position);away.y=0;away.normalize();c.position.addScaledVector(away,dt*4);c.rotation.y=Math.atan2(-away.x,-away.z)}else if(c.userData.ai){if(d>4){const a=Math.atan2(player.position.x-c.position.x,player.position.z-c.position.z);c.rotation.y=a;c.position.x+=Math.sin(a)*dt*.6;c.position.z+=Math.cos(a)*dt*.6}c.userData.limbs.forEach((l,i)=>l.rotation.x=Math.sin(c.userData.walk*2+(i%2)*Math.PI)*.12);}}
 if(held){const holdpos=player.position.clone().add(new THREE.Vector3(Math.sin(yaw),.7,-Math.cos(yaw)).multiplyScalar(2));held.position.lerp(holdpos,.15);held.rotation.y+=dt*.5}
 for(let i=bubbles.length-1;i>=0;i--){const b=bubbles[i];b.mesh.position.addScaledVector(b.vel,dt);b.life-=dt;if(b.life<=0){scene.remove(b.mesh);bubbles.splice(i,1)}}
 }
 const target=new THREE.Vector3(player.position.x,player.position.y+1.25,player.position.z);const dist=10;camera.position.set(target.x+Math.sin(yaw)*Math.cos(pitch)*dist,target.y+4+Math.sin(pitch)*dist,target.z+Math.cos(yaw)*Math.cos(pitch)*dist);camera.lookAt(target);
}
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000);last=now;if(started)tick(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
// Keep the initial world welcoming and populated with a few tactile toys.
for(const [t,p] of [['Barrel',[5,0,2]],['Crate',[-5,0,4]],['Furniture',[4,0,-1]],['Lamp',[-8,0,-5]]])prop(t,p);
buildMap('Sunnyvale');
</script>
</body></html>

